        "properties": {
            "log_line": {"type": "string", "description": "Linha do log do Nginx."}
        },
        "required": ["log_line"]
    }
    when_to_use = "Usada para estruturar logs brutas do Nginx em JSON."
    when_not_to_use = "Não deve ser usada para logs em outros formatos."

    def execute(self, log_line: str) -> str:
        pat = r'^(\S+) \S+ \S+ \[(\S+ \S+)\] "(\S+) (\S+) \S+" (\d+) (\d+)'
        match = re.match(pat, log_line)
        if not match:
            return json.dumps({"error": "Invalid format"})
        ip, date_str, method, path, status, size = match.groups()
        return json.dumps({
            "ip": ip, "date": date_str, "method": method,
            "path": path, "status": int(status), "bytes": int(size)
        })

