class LatencyP99Calculator:
    name = "latency_p99_calculator"
    description = "Calcula o percentil 99 das latências fornecidas."
    input_schema = {
        "type": "object",
        "properties": {
            "latencies": {
                "type": "array",
                "items": {"type": "number"},
                "description": "Lista de latências em ms."
            }
        },
        "required": ["latencies"]
    }
    when_to_use = "Para calcular a latência de cauda (P99) de uma aplicação."
    when_not_to_use = "Para outras métricas estatísticas não relacionadas a percentis."

    def execute(self, latencies: list[float]) -> str:
        if not latencies:
            return json.dumps({"error": "Empty list"})
        sorted_l = sorted(latencies)
        idx = math.ceil(len(sorted_l) * 0.99) - 1
        idx = max(0, min(idx, len(sorted_l) - 1))
        return json.dumps({"p99_latency": sorted_l[idx]})

