class IniConfigParser:
    name = "ini_config_parser"
    description = "Parseia um conteúdo em formato INI para um JSON aninhado por seções."
    input_schema = {
        "type": "object",
        "properties": {
            "ini_content": {"type": "string", "description": "Conteúdo do arquivo INI."}
        },
        "required": ["ini_content"]
    }
    when_to_use = "Para carregar e processar parâmetros de configurações no formato clássico INI."
    when_not_to_use = "Para parsear outros formatos de configuração como YAML ou JSON."

    def execute(self, ini_content: str) -> str:
        config = {}
        current_section = "default"
        for line in ini_content.split('\n'):
            line = line.strip()
            if not line or line.startswith(';') or line.startswith('#'):
                continue
            if line.startswith('[') and line.endswith(']'):
                current_section = line[1:-1].strip()
                config[current_section] = {}
            elif '=' in line:
                k, v = line.split('=', 1)
                config.setdefault(current_section, {})[k.strip()] = v.strip()
        return json.dumps(config)

SPEC = IniConfigParser()

