class JaccardSimilarityCalc:
    name = "jaccard_similarity_calc"
    description = "Calcula a similaridade de Jaccard entre duas listas de termos."
    input_schema = {
        "type": "object",
        "properties": {
            "list_a": {"type": "array", "items": {"type": "string"}, "description": "Primeira lista de termos."},
            "list_b": {"type": "array", "items": {"type": "string"}, "description": "Segunda lista de termos."}
        },
        "required": ["list_a", "list_b"]
    }
    when_to_use = "Para avaliar o grau de sobreposição de termos ou tokens entre dois textos."
    when_not_to_use = "Quando for necessária uma similaridade semântica ou baseada em embeddings."

    def execute(self, list_a: list[str], list_b: list[str]) -> str:
        set_a = set(list_a)
        set_b = set(list_b)
        intersection = len(set_a.intersection(set_b))
        union = len(set_a.union(set_b))
        if union == 0:
            return json.dumps({"similarity": 0.0})
        similarity = intersection / union
        return json.dumps({"similarity": round(similarity, 4)})

