class SemicolonCsvParser:
    name = "semicolon_csv_parser"
    description = "Parseia conteúdo CSV delimitado por ponto e vírgula em JSON."
    input_schema = {
        "type": "object",
        "properties": {
            "csv_content": {"type": "string", "description": "Linhas CSV de entrada."}
        },
        "required": ["csv_content"]
    }
    when_to_use = "Para ler arquivos CSV exportados do Excel com ponto e vírgula."
    when_not_to_use = "Para CSVs padrão delimitados por vírgula ou TSVs."

    def execute(self, csv_content: str) -> str:
        lines = csv_content.strip().split('\n')
        if not lines:
            return json.dumps([])
        headers = [h.strip() for h in lines[0].split(';')]
        result = []
        for line in lines[1:]:
            values = [v.strip() for v in line.split(';')]
            if len(values) == len(headers):
                result.append(dict(zip(headers, values)))
        return json.dumps(result)

