    }
    when_to_use = "Para triagem inicial rápida de feedback de clientes ou reviews."
    when_not_to_use = "Para entender nuances complexas, ironia ou em análises multilingues."

    def execute(self, text: str) -> str:
        positives = {"maravilhoso", "excelente", "rápido", "bom", "gostei", "ótimo"}
        negatives = {"ruim", "péssimo", "lento", "demorou", "odeiei", "falhou"}
        words = text.lower().split()
        score = 0
        for w in words:
            w_clean = w.strip(".,!?;")
            if w_clean in positives:
                score += 1
            elif w_clean in negatives:
                score -= 1
        sentiment = "neutro"
        if score > 0:
            sentiment = "positivo"
        elif score < 0:
            sentiment = "negativo"
        return json.dumps({"score": score, "sentiment": sentiment})

SPEC = SimpleSentimentDetector()

