class PiiDetectorTool:
    name = "pii_detector_tool"
    description = "Escaneia e sinaliza a presença de CPFs e telefones no texto de entrada."
    input_schema = {
        "type": "object",
        "properties": {
            "text": {"type": "string", "description": "Texto bruto."}
        },
