arguments.content:
from agentforge.tools.registry import ToolSpec
import json

def config_validator(config: dict, schema: dict) -> str:
    errors = []
    for k, v in schema.items():
        if k not in config:
            errors.append(f"Chave obrigatória ausente: {k}")
        else:
            expected_type = v.get("type")
            actual_type = type(config[k]).__name__
            type_map = {"string": "str", "integer": "int", "boolean": "bool", "number": "float"}
            mapped_type = type_map.get(expected_type, expected_type)
            if expected_type == "integer" and isinstance(config[k], int):
                continue
            if expected_type == "number" and isinstance(config[k], (int, float)):
                continue
            if actual_type != mapped_type:
                errors.append(f"Tipo inválido para a chave '{k}': esperado {expected_type}, obtido {actual_type}")
    return json.dumps({"valid": len(errors) == 0, "errors": errors})

SPEC = ToolSpec(
    name="config_validator",
    description="Valida configurações contra um schema básico definido em JSON.",
    parameters={
        "type": "object",
        "properties": {
            "config": {"type": "object", "description": "Dicionário de configuração a validar."},
            "schema": {"type": "object", "description": "Schema básico com tipos esperados."}
        },
        "required": ["config", "schema"]
    }
)

## Guia de Integração e Tokenização

Para garantir conformidade com as regras de segurança PCI-DSS, os dados do cartão de crédito nunca devem tocar o seu servidor diretamente. Use o SDK front-end para tokenizar o cartão e obter um `payment_method_id`.

```javascript
// Exemplo Front-end (Tokenização)
const stripe = GlobalPay('pk_test_1234');
const cardElement = stripe.elements.create('card');

stripe.createToken(cardElement).then(function(result) {
  if (result.error) {
    console.error(result.error.message);
  } else {
    // Envie o token.id para o seu servidor
    sendTokenToServer(result.token.id);
  }
});
```

### Captura Manual vs Automática
Por padrão, os pagamentos são capturados no momento em que são criados. Se preferir a captura manual (autorização temporária):
1. Envie `capture=false` na criação.
2. Capture o pagamento em até 7 dias enviando `POST /charges/{id}/capture`.

