## Implementação do Loop de Reconciliação (Go)

O loop de reconciliação lê o estado atual do recurso especificado no cluster e realiza ações para igualar ao estado desejado.

```go
package controllers

import (
	"context"
	dbv1alpha1 "company.com/operator/api/v1alpha1"
	"k8s.io/apimachinery/pkg/runtime"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

type MyDatabaseReconciler struct {
	client.Client
	Scheme *runtime.Scheme
}

func (r *MyDatabaseReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	var db dbv1alpha1.MyDatabase
	if err := r.Get(ctx, req.NamespacedName, &db); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}

	// Lógica para criar os StatefulSets se não existirem
	err := r.ensureStatefulSet(ctx, &db)
	if err != nil {
		return ctrl.Result{Requeue: true}, err
	}

	return ctrl.Result{}, nil
}
```

