import "errors"

func ProcessJobs(jobs []string) error {
    ch := make(chan error)
    for _, job := range jobs {
        go func(j string) {
            if j == "" {
                ch <- errors.New("empty job") // Risco de vazamento se o canal não for lido após erro inicial
                return
            }
            // processamento simulado
            ch <- nil
        }(job)
    }

    for i := 0; i < len(jobs); i++ {
        err := <-ch
        if err != nil {
            return err // Retorna imediatamente e deixa goroutines pendentes travadas no ch <- nil
        }
    }
    return nil
}

