from agentforge.tools.registry import ToolSpec

def process_analyzer(processes: str) -> list:
    """Extrai processos que consomem mais de 10% de CPU ou Memória."""
    result = []
    lines = processes.strip().split("\n")[1:]
    for line in lines:
        parts = line.split()
        if len(parts) >= 4:
            try:
                cpu = float(parts[2])
                mem = float(parts[3])
                if cpu > 10.0 or mem > 10.0:
                    result.append({"pid": parts[1], "cpu": cpu, "mem": mem, "command": " ".join(parts[10:])})
            except ValueError:
                continue
    return result

