def sentiment_analyser(tweets: list) -> dict:
    """Conta quantos tweets possuem termos positivos ou negativos."""
    positive_words = {"bom", "otimo", "excelente", "love", "maravilhoso"}
    negative_words = {"ruim", "pessimo", "odiei", "hate", "lixo"}
    pos_count = 0
    neg_count = 0
    for tweet in tweets:
        text = tweet.get("text", "").lower()
        if any(w in text for w in positive_words):
