from agentforge.tools.registry import ToolSpec

def amortization_calculator(principal: float, periods: int, interest_rate: float, system: str) -> dict:
    """Calcula a parcela constante na tabela Price."""
    if system.lower() == "price":
        pmt = (principal * interest_rate) / (1 - (1 + interest_rate) ** (-periods))
        total_payment = pmt * periods
        total_interest = total_payment - principal
        return {"installment": round(pmt, 2), "total_interest": round(total_interest, 2)}
    return {}

