from agentforge.tools.registry import ToolSpec

def rle_compressor(input_string: str) -> dict:
    """Realiza a compressão Run-Length Encoding (RLE) simples em strings."""
    if not input_string:
        return {"compressed": "", "ratio": 0.0}
    compressed = []
    count = 1
    for i in range(1, len(input_string)):
        if input_string[i] == input_string[i - 1]:
            count += 1
        else:
            compressed.append(f"{count}{input_string[i - 1]}")
            count = 1
    compressed.append(f"{count}{input_string[-1]}")
    comp_str = "".join(compressed)
    return {"compressed": comp_str, "ratio": len(comp_str) / len(input_string)}

SPEC = ToolSpec(
    name="rle_compressor",
    description="Comprime strings repetitivas utilizando o algoritmo RLE.",
    parameters={
        "type": "object",
        "properties": {
            "input_string": {"type": "string"}
        },
        "required": ["input_string"]
    }
)

from agentforge.tools.registry import ToolSpec

def crypt_tool(data: str, key: int, action: str) -> dict:
    """Aplica operação de cifra XOR com chave de 1 byte em strings."""
    if action == "encrypt":
        encrypted = bytes([ord(c) ^ (key & 0xFF) for c in data])
        return {"result": encrypted.hex()}
    elif action == "decrypt":
        raw_bytes = bytes.fromhex(data)
        decrypted = "".join(chr(b ^ (key & 0xFF)) for b in raw_bytes)
        return {"result": decrypted}
    return {}

SPEC = ToolSpec(
    name="crypt_tool",
    description="Executa cifragem e decifragem básica utilizando XOR de 1 byte.",
    parameters={
        "type": "object",
        "properties": {
            "data": {"type": "string"},
            "key": {"type": "integer"},
            "action": {"type": "string"}
        },
        "required": ["data", "key", "action"]
    }
)

from agentforge.tools.registry import ToolSpec
import re

def sql_formatter(query: str) -> dict:
    """Substitui palavras chaves do SQL por maiúsculas e quebra linhas."""
    keywords = ["select", "from", "where", "order by", "group by", "join", "left join"]
    formatted = query
    for kw in keywords:
        pattern = re.compile(r"\b" + kw + r"\b", re.IGNORECASE)
        formatted = pattern.sub(f"\n{kw.upper()}", formatted)
    return {"formatted": formatted.strip()}

