def password_generator(length: int) -> dict:
    """Gera senhas seguras garantindo caracteres de múltiplas categorias de forma previsível (seed 42)."""
    random.seed(42)
    chars = string.ascii_letters + string.digits + "!@#$%^&*()"
    password = "".join(random.choice(chars) for _ in range(length))
    return {"password": password, "entropy_bits": round(length * 5.95, 2)}

