from agentforge.tools.registry import ToolSpec

def schema_validator(payload: dict, schema: dict) -> dict:
    """Valida tipos primitivos no payload comparando com a especificação fornecida."""
    errors = []
    type_map = {"int": int, "str": str, "bool": bool, "float": float}
    for field, type_name in schema.items():
        if field not in payload:
            errors.append(f"Missing field: {field}")
            continue
        expected_type = type_map.get(type_name)
        if expected_type and not isinstance(payload[field], expected_type):
            errors.append(f"Field '{field}' expects {type_name}, got {type(payload[field]).__name__}")
    return {"valid": len(errors) == 0, "errors": errors}

SPEC = ToolSpec(
    name="schema_validator",
    description="Valida se os campos de um dicionário respeitam os tipos indicados em um esquema.",
    parameters={
        "type": "object",
        "properties": {
            "payload": {"type": "object"},
            "schema": {"type": "object"}
        },
        "required": ["payload", "schema"]
    }
)

