def sales_calculator(csv_content: str) -> dict:
    """Calcula o faturamento total agrupado por produto de uma string CSV."""
    reader = csv.DictReader(io.StringIO(csv_content.strip()))
    result = {}
    for row in reader:
        prod = row['product']
