def text_word_frequency(text: str) -> dict:
    """Calcula frequencia de palavras ignorando stopwords basicas."""
    stopwords = {'o', 'a', 'de', 'do', 'da', 'em', 'um', 'uma', 'e', 'os', 'as'}
    words = [w.strip(',.!?()').lower() for w in text.split()]
    freq = {}
    for w in words:
        if w and w not in stopwords:
            freq[w] = freq.get(w, 0) + 1
    return freq

