from agentforge.tools.registry import ToolSpec
import re

def date_formatter(dates_text: str) -> list:
    """Converte datas de formatos comuns para ISO YYYY-MM-DD."""
    lines = dates_text.strip().split('\n')
    result = []
    for line in lines:
        line = line.strip()
        if re.match(r'^\d{4}-\d{2}-\d{2}$', line):
            result.append(line)
        elif '/' in line:
            d, m, y = line.split('/')
            result.append(f'{y}-{m}-{d}')
        elif '-' in line:
            parts = line.split('-')
            if len(parts[0]) == 2:
                d, m, y = parts
                result.append(f'{y}-{m}-{d}')
            else:
                result.append(line)
    return result

SPEC = ToolSpec(
    name='date_formatter',
    description='Normaliza datas para o padrao ISO YYYY-MM-DD.',
    parameters={
        'type': 'object',
        'properties': {
            'dates_text': {'type': 'string'}
        },
        'required': ['dates_text']
    }
)

from agentforge.tools.registry import ToolSpec
import re

def phone_sanitizer(phones_text: str) -> list:
    """Formata contatos telefonicos mantendo apenas digitos com DDI +55 padronizado."""
    lines = phones_text.strip().split('\n')
    result = []
    for line in lines:
        digits = re.sub(r'\D', '', line)
        if not digits.startswith('55'):
