from agentforge.tools.registry import ToolSpec
import json

def markdown_table_generator(users_json: str) -> str:
    """Converte lista de usuarios em formato dicionario JSON para uma tabela Markdown."""
    users = json.loads(users_json)
    if not users:
        return ''
    headers = list(users[0].keys())
    header_row = '| ' + ' | '.join(headers) + ' |'
    separator_row = '| ' + ' | '.join(['---'] * len(headers)) + ' |'
    rows = []
    for u in users:
        rows.append('| ' + ' | '.join(str(u.get(h, '')) for h in headers) + ' |')
    return '\n'.join([header_row, separator_row] + rows)

SPEC = ToolSpec(
    name='markdown_table_generator',
    description='Cria tabelas em Markdown a partir de colecoes JSON.',
    parameters={
        'type': 'object',
        'properties': {
            'users_json': {'type': 'string'}
        },
        'required': ['users_json']
    }
)

