import json

def sql_query_builder(query_definition: str) -> str:
    """Gera uma declaracao SQL SELECT parametrizada a partir da definicao fornecida."""
    data = json.loads(query_definition)
    table = data.get('table')
    fields = ', '.join(data.get('fields', ['*']))
    where_dict = data.get('where', {})
    sql = f'SELECT {fields} FROM {table}'
    if where_dict:
        conds = [f'{k} = :{k}' for k in where_dict.keys()]
        sql += ' WHERE ' + ' AND '.join(conds)
    return sql

