)

from agentforge.tools.registry import ToolSpec

def version_comparator(versions_text: str) -> dict:
    """Compara duas versoes semanticas lidas de uma string bruta."""
    lines = versions_text.strip().split('\n')
    current = ''
    latest = ''
    for line in lines:
        if line.startswith('current:'):
            current = line.split(':')[1].strip()
        elif line.startswith('latest:'):
            latest = line.split(':')[1].strip()

    c_parts = [int(p) for p in current.split('.')]
    l_parts = [int(p) for p in latest.split('.')]

    update_type = None
    if l_parts[0] > c_parts[0]:
        update_type = 'major'
    elif l_parts[0] == c_parts[0] and l_parts[1] > c_parts[1]:
        update_type = 'minor'
    elif l_parts[0] == c_parts[0] and l_parts[1] == c_parts[1] and l_parts[2] > c_parts[2]:
        update_type = 'patch'

    return {
        'update_available': update_type is not None,
        'current': current,
        'latest': latest,
        'type': update_type
    }

SPEC = ToolSpec(
    name='version_comparator',
    description='Compara duas strings de versao semantica para verificar atualizacoes.',
    parameters={
        'type': 'object',
        'properties': {
            'versions_text': {'type': 'string'}
        },
        'required': ['versions_text']
    }
)

